namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a weekend morning.",
                Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "3 tbsp sugar", "2 tsp baking powder", "¼ tsp salt", "3 tbsp melted butter"],
                Steps = ["Mix dry ingredients in a bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Cook on a buttered griddle over medium heat until bubbles form, then flip.", "Serve with maple syrup and fresh berries."],
                Ratings = [5, 4, 5, 4, 5]
            },
            new()
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Description = "Simple, healthy, and endlessly customizable.",
                Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "Juice of ½ lemon", "Salt and pepper", "Red pepper flakes", "1 egg (optional)"],
                Steps = ["Toast the bread until golden and crisp.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread onto toast and top with red pepper flakes.", "Add a fried or poached egg on top if desired."],
                Ratings = [4, 4, 3, 5]
            },
            new()
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Dinner",
                Description = "A creamy Roman classic made without cream.",
                Ingredients = ["400g spaghetti", "200g guanciale or pancetta", "4 egg yolks", "1 cup grated Pecorino Romano", "Black pepper"],
                Steps = ["Cook spaghetti in salted boiling water until al dente.", "Crisp the guanciale in a skillet over medium heat.", "Whisk egg yolks with Pecorino and plenty of black pepper.", "Toss hot drained pasta with guanciale, then remove from heat.", "Stir in the egg mixture quickly, tossing to create a creamy sauce."],
                Ratings = [5, 5, 5, 4, 5]
            },
            new()
            {
                Id = 4, Title = "Chicken Stir-Fry", Category = "Dinner",
                Description = "A quick weeknight dinner loaded with vegetables.",
                Ingredients = ["2 chicken breasts, sliced", "1 bell pepper, sliced", "1 cup broccoli florets", "2 cloves garlic", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp cornstarch", "Cooked rice for serving"],
                Steps = ["Toss chicken slices with cornstarch and 1 tbsp soy sauce.", "Heat sesame oil in a wok over high heat.", "Stir-fry chicken until golden, then set aside.", "Cook vegetables and garlic for 2–3 minutes.", "Return chicken, add remaining soy sauce, and toss until glazed. Serve over rice."],
                Ratings = [4, 5, 4]
            },
            new()
            {
                Id = 5, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Crispy edges, chewy centers — the perfect cookie.",
                Ingredients = ["2¼ cups flour", "1 cup butter, softened", "¾ cup sugar", "¾ cup brown sugar", "2 eggs", "1 tsp vanilla", "1 tsp baking soda", "1 tsp salt", "2 cups chocolate chips"],
                Steps = ["Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour, baking soda, and salt.", "Fold in chocolate chips.", "Scoop onto baking sheets and bake at 375°F for 9–11 minutes."],
                Ratings = [5, 5, 4, 5, 5, 5]
            },
            new()
            {
                Id = 6, Title = "Lemon Bars", Category = "Desserts",
                Description = "Tangy and sweet with a buttery shortbread crust.",
                Ingredients = ["1 cup butter", "½ cup powdered sugar", "2 cups flour", "4 eggs", "1½ cups sugar", "¼ cup lemon juice", "2 tbsp lemon zest"],
                Steps = ["Mix butter, powdered sugar, and flour into a dough. Press into a 9x13 pan.", "Bake crust at 350°F for 20 minutes.", "Whisk eggs, sugar, lemon juice, and zest.", "Pour over hot crust and bake 25 minutes more.", "Cool completely, dust with powdered sugar, and cut into bars."],
                Ratings = [4, 5, 4]
            },
            new()
            {
                Id = 7, Title = "Caesar Salad", Category = "Lunch",
                Description = "Crisp romaine with a rich, garlicky dressing.",
                Ingredients = ["1 head romaine lettuce", "½ cup Parmesan shavings", "1 cup croutons", "2 cloves garlic", "2 anchovy fillets", "1 egg yolk", "1 tbsp Dijon mustard", "¼ cup olive oil", "Juice of 1 lemon"],
                Steps = ["Mash garlic and anchovies into a paste.", "Whisk in egg yolk, mustard, and lemon juice.", "Slowly drizzle in olive oil while whisking to emulsify.", "Tear romaine into pieces and toss with dressing.", "Top with Parmesan shavings and croutons."],
                Ratings = [4, 4, 5]
            },
            new()
            {
                Id = 8, Title = "Grilled Cheese Sandwich", Category = "Lunch",
                Description = "Golden, buttery, and oozing with melted cheese.",
                Ingredients = ["2 slices white bread", "2 slices cheddar cheese", "1 tbsp butter"],
                Steps = ["Butter one side of each bread slice.", "Place cheese between the unbuttered sides.", "Cook in a skillet over medium-low heat until golden on each side."],
                Ratings = [5, 4, 5, 5]
            },
        ];
        _nextId = 9;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
            recipe.Ratings.Add(stars);
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title.Trim(),
            Category = category.Trim(),
            Description = "",
            Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        });
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService Recipes

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _hovered ? "hovered" : "") @(star <= _selected ? "selected" : "")"
              @onmouseover="() => _hovered = star"
              @onmouseout="() => _hovered = 0"
              @onclick="() => Rate(star)"
              title="Rate @star star@(star > 1 ? "s" : "")">
            ★
        </span>
    }
    <span class="rating-info">
        @if (_submitted)
        {
            <span class="text-success">Thanks!</span>
        }
        @if (Recipe is not null && Recipe.Ratings.Count > 0)
        {
            <span>@Recipe.AverageRating / 5 (@Recipe.Ratings.Count ratings)</span>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private Recipe? Recipe => Recipes.GetById(RecipeId);
    private int _hovered;
    private int _selected;
    private bool _submitted;

    private void Rate(int stars)
    {
        _selected = stars;
        _submitted = true;
        Recipes.AddRating(RecipeId, stars);
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 2px;
    margin: 0.75rem 0;
}

.star {
    font-size: 1.75rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s, transform 0.15s;
    user-select: none;
}

.star:hover {
    transform: scale(1.2);
}

.star.hovered,
.star.selected {
    color: #f5a623;
}

.rating-info {
    margin-left: 0.75rem;
    font-size: 0.9rem;
    color: #666;
    display: flex;
    gap: 0.5rem;
}

