arguments.new_str:
@page "/"
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>RecipeShare — Home</PageTitle>

<div class="text-center mb-4">
    <h1>🍳 RecipeShare</h1>
    <p class="lead">Discover and share delicious recipes with our community.</p>
</div>

<h2>Browse by Category</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4 mt-2">
    @foreach (var category in Recipes.GetCategories())
    {
        var recipes = Recipes.GetByCategory(category);
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">
                        <span class="category-icon">@CategoryIcon(category)</span>
                        @category
                    </h3>
                    <p class="text-muted">@recipes.Count recipe@(recipes.Count != 1 ? "s" : "")</p>
                    <a href="/category/@Uri.EscapeDataString(category)" class="btn btn-outline-primary">
                        View Recipes
                    </a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryIcon(string category) => category switch
    {
        "Breakfast" => "🥞",
        "Lunch" => "🥗",
        "Dinner" => "🍝",
        "Desserts" => "🍪",
        _ => "🍽️"
    };
}

arguments.file_text:
@page "/category/{CategoryName}"
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

@if (recipeList.Count == 0)
{
    <h2>No recipes found in "@CategoryName"</h2>
    <a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h2>@CategoryName Recipes</h2>

    <div class="row row-cols-1 row-cols-md-2 g-4 mt-2">
        @foreach (var recipe in recipeList)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text text-muted">@recipe.Description</p>
                        @if (recipe.Ratings.Count > 0)
                        {
                            <p class="mb-2">
                                <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))</span>
                                <span class="text-muted">@recipe.AverageRating / 5</span>
                            </p>
                        }
                        <a href="/recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = "";

    private List<Recipe> recipeList = [];

    protected override void OnParametersSet()
    {
        recipeList = Recipes.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Components.Shared
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <h2>Recipe not found</h2>
    <a href="/" class="btn btn-secondary mt-3">← Back to Home</a>
}
else
{
