@page "/"
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>RecipeShare — Home</PageTitle>

<div class="text-center mb-4">
    <h1>🍳 RecipeShare</h1>
    <p class="lead">Discover and share delicious recipes with our community.</p>
</div>

<h2>Browse by Category</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4 mt-2">
    @foreach (var category in Recipes.GetCategories())
    {
        var recipes = Recipes.GetByCategory(category);
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">
                        <span class="category-icon">@CategoryIcon(category)</span>
                        @category
                    </h3>
                    <p class="text-muted">@recipes.Count recipe@(recipes.Count != 1 ? "s" : "")</p>
                    <a href="/category/@Uri.EscapeDataString(category)" class="btn btn-outline-primary">
                        View Recipes
                    </a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryIcon(string category) => category switch
    {
        "Breakfast" => "🥞",
        "Lunch" => "🥗",
        "Dinner" => "🍝",
        "Desserts" => "🍪",
        _ => "🍽️"
    };
}

