            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h2>@CategoryName Recipes</h2>

    <div class="row row-cols-1 row-cols-md-2 g-4 mt-2">
        @foreach (var recipe in recipeList)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text text-muted">@recipe.Description</p>
                        @if (recipe.Ratings.Count > 0)
                        {
                            <p class="mb-2">
                                <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))</span>
                                <span class="text-muted">@recipe.AverageRating / 5</span>
                            </p>
                        }
                        <a href="/recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = "";

    private List<Recipe> recipeList = [];

    protected override void OnParametersSet()
    {
        recipeList = Recipes.GetByCategory(CategoryName);
    }
}

