@page "/recipe/{Id:int}"
@using RecipeShare.Components.Shared
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <h2>Recipe not found</h2>
    <a href="/" class="btn btn-secondary mt-3">← Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@Uri.EscapeDataString(recipe.Category)">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h2>@recipe.Title</h2>
    @if (!string.IsNullOrEmpty(recipe.Description))
    {
        <p class="lead">@recipe.Description</p>
    }

    <StarRating RecipeId="recipe.Id" />

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card shadow-sm">
                <div class="card-header"><strong>🧾 Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <div class="card shadow-sm">
                <div class="card-header"><strong>👩‍🍳 Steps</strong></div>
                <ol class="list-group list-group-flush list-group-numbered">
                    @foreach (var step in recipe.Steps)
                    {
                        <li class="list-group-item">@step</li>
                    }
                </ol>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = Recipes.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h2>📝 Submit a Recipe</h2>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "<strong>@_title</strong>" has been added.
        <a href="/category/@Uri.EscapeDataString(_category)">View it now →</a>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="mt-3">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="_title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            @if (_errors.ContainsKey("title"))
            {
                <div class="text-danger">@_errors["title"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="_category" class="form-select">
                <option value="">— Select a category —</option>
                <option value="Breakfast">Breakfast</option>
                <option value="Lunch">Lunch</option>
                <option value="Dinner">Dinner</option>
                <option value="Desserts">Desserts</option>
            </InputSelect>
            @if (_errors.ContainsKey("category"))
            {
                <div class="text-danger">@_errors["category"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" @bind-Value="_ingredients" class="form-control" rows="5"
                           placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            @if (_errors.ContainsKey("ingredients"))
            {
                <div class="text-danger">@_errors["ingredients"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" @bind-Value="_steps" class="form-control" rows="5"
                           placeholder="One step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Bake for 30 minutes" />
            @if (_errors.ContainsKey("steps"))
            {
                <div class="text-danger">@_errors["steps"]</div>
            }
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private string _title = "";
    private string _category = "";
    private string _ingredients = "";
    private string _steps = "";
    private bool _submitted;
    private Dictionary<string, string> _errors = new();

    private void HandleSubmit()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(_title))
            _errors["title"] = "Please enter a recipe title.";
        if (string.IsNullOrWhiteSpace(_category))
            _errors["category"] = "Please select a category.";
        if (string.IsNullOrWhiteSpace(_ingredients))
            _errors["ingredients"] = "Please enter at least one ingredient.";
        if (string.IsNullOrWhiteSpace(_steps))
            _errors["steps"] = "Please enter at least one step.";

        if (_errors.Count > 0)
            return;

        Recipes.AddRecipe(_title, _category, _ingredients, _steps);
        _submitted = true;
    }

    private void Reset()
    {
        _title = "";
        _category = "";
        _ingredients = "";
        _steps = "";
        _submitted = false;
        _errors.Clear();
    }
}

